INSERT INTO `users` (`id`, `username`, `password`, `rol_id`, `created`, `modified`, `doctor_id`, `estado_user`)
SELECT `id`, `username`, `password`,
  CASE `rol` WHEN 1 THEN 1 WHEN 3 THEN 2 WHEN 5 THEN 5 ELSE `rol` END,
  `created`, `modified`, `doctor_id`, 'A'
FROM `_tmp_users`
ON DUPLICATE KEY UPDATE `username`=VALUES(`username`), `password`=VALUES(`password`),
  `rol_id`=VALUES(`rol_id`), `doctor_id`=VALUES(`doctor_id`), `modified`=VALUES(`modified`);

