INSERT INTO `pacientes` (`id`, `nombre`, `apellido`, `telefono_celular`, `estado`, `created`, `modified`)
SELECT `id`, `nombre`, `apellido`, `telefono_celular`, 'A', `created`, `modified`
FROM `_tmp_pacientes1`
ON DUPLICATE KEY UPDATE `nombre`=VALUES(`nombre`), `apellido`=VALUES(`apellido`),
  `telefono_celular`=VALUES(`telefono_celular`), `modified`=VALUES(`modified`);

-- 7. pacientes → historias_clinicas (remapeo de columnas)
CREATE TEMPORARY TABLE IF NOT EXISTS `_tmp_pacientes` (
  `id` int(11) NOT NULL, `paciente_id` int(11) NOT NULL,
  `dni` varchar(20) DEFAULT NULL, `ruc` varchar(20) DEFAULT NULL,
  `fecha_nacimiento` date DEFAULT NULL, `sexo` varchar(15) DEFAULT NULL,
  `edad` int(11) DEFAULT NULL, `nombre_apoderado` varchar(50) DEFAULT NULL,
  `parentesco_apoderado` varchar(20) DEFAULT NULL, `direccion` varchar(100) DEFAULT NULL,
  `distrito` varchar(50) DEFAULT NULL, `codigo_postal` varchar(10) DEFAULT NULL,
  `email` varchar(50) DEFAULT NULL, `telefono_oficina` varchar(20) DEFAULT NULL,
  `centro_trabajo` varchar(50) DEFAULT NULL, `centro_estudio` varchar(50) DEFAULT NULL,
  `recomendacion` varchar(255) DEFAULT NULL,
  `created` datetime NOT NULL, `modified` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

