INSERT INTO `historias_clinicas` (`id`, `paciente_id`, `dni`, `fecha_nacimiento`, `edad`, `sexo`, `email`, `parentesco`, `apoderado`, `recomendado`, `direccion`, `ocupacion`, `created`, `modified`)
SELECT `id`, `paciente_id`, `dni`, `fecha_nacimiento`, `edad`, `sexo`, `email`,
       `parentesco_apoderado`, `nombre_apoderado`, `recomendacion`, `direccion`, `centro_trabajo`,
       `created`, `modified`
FROM `_tmp_pacientes`
ON DUPLICATE KEY UPDATE `dni`=VALUES(`dni`), `fecha_nacimiento`=VALUES(`fecha_nacimiento`),
  `sexo`=VALUES(`sexo`), `email`=VALUES(`email`),
  `direccion`=VALUES(`direccion`), `modified`=VALUES(`modified`);

